    "intro": "흩어진 세상 속에서 하나님은 한 사람을 부르십니다. 갈 곳을 다 알려 주지 않은 채 떠나라고 하시고, 아이가 없는 부부에게 셀 수 없는 자손을 약속하십니다. 아브라함은 믿기도 하고 웃기도 하고 때로는 스스로 길을 만들려 합니다. 그때마다 하나님은 같은 질문 앞에 그를 세우십니다. 여호와께 너무 어려운 일이 있겠느냐. 약속이 늦어지는 시간을 그와 함께 걸어가 보십시오.",
